package com.englishhero.reading.translation;
import java.util.*;import java.time.*;
import org.springframework.jdbc.core.*;import org.springframework.jdbc.support.GeneratedKeyHolder;import org.springframework.stereotype.Repository;
import com.englishhero.web.BusinessException;
import static com.englishhero.reading.translation.SelectionTranslationDtos.*;
@Repository
public class SelectionTranslationMapper {
 private final JdbcTemplate jdbc;private final tools.jackson.databind.ObjectMapper json;public SelectionTranslationMapper(JdbcTemplate j,tools.jackson.databind.ObjectMapper json){jdbc=j;this.json=json;}public JdbcTemplate sql(){return jdbc;}
 public RowMapper<Job> jobs(){return (r,n)->new Job(r.getLong("id"),r.getLong("user_id"),r.getString("source_text"),r.getString("lease_token"),r.getDate("budget_day").toLocalDate(),r.getLong("reserved_microusd"),r.getTimestamp("created_at").toInstant(),r.getTimestamp("lease_until")==null?null:r.getTimestamp("lease_until").toInstant(),r.getString("status"),r.getString("mode"),r.getString("model"),r.getInt("source_characters"),r.getDate("quota_month")==null?null:r.getDate("quota_month").toLocalDate());}
 public long insert(String sql,Object...args){var key=new GeneratedKeyHolder();jdbc.update(c->{var p=c.prepareStatement(sql,java.sql.Statement.RETURN_GENERATED_KEYS);for(int i=0;i<args.length;i++)p.setObject(i+1,args[i]);return p;},key);return Objects.requireNonNull(key.getKey()).longValue();}
 public Task dto(long user,long id){return jdbc.query("SELECT id,source_text,status,translated_text,model,error_code,reserved_microusd,settled_microusd,input_tokens,output_tokens,mode,analysis_json,source_characters FROM reading_selection_translation WHERE user_id=? AND id=?",(r,n)->{String state=r.getString("status");Long settled=(Long)r.getObject("settled_microusd");String budget=com.englishhero.practice.review.PracticeReviewMapper.budgetStatus(state,settled,(Long)r.getObject("input_tokens"),(Long)r.getObject("output_tokens"));if(BaiduTranslationProperties.MODEL.equals(r.getString("model"))){budget="QUEUED".equals(state)||"RUNNING".equals(state)?"RESERVED":"SUCCEEDED".equals(state)?"SETTLED":BaiduTranslationJobsSupport.unsent(r.getString("error_code"))?"RELEASED":"UNKNOWN";}long micro=settled==null?r.getLong("reserved_microusd"):settled;return new Task(r.getString("id"),r.getString("source_text"),state,r.getString("translated_text"),r.getString("model"),r.getString("error_code"),budget,(micro*20+2)/3,r.getString("mode"),r.getString("analysis_json")==null?null:json.readTree(r.getString("analysis_json")),r.getInt("source_characters"));},user,id).stream().findFirst().orElseThrow(()->new BusinessException(404,"SELECTION_TRANSLATION_NOT_FOUND","翻译任务不存在"));}
}
